mapper.select:
SELECT * FROM shopion.tOprFaq

    AND ChnlCode = #{pChnlCode}
    AND FaqNo = #{pFaqNo}
    AND FaqTitle LIKE CONCAT('%',#{pFaqTitle},'%')
    AND FaqCntnts LIKE CONCAT('%',#{pFaqCntnts},'%')
    AND CustConsltType = #{pCustConsltType}

ORDER BY ${sidx} ${sord}

mapper.update:
UPDATE shopion.tOprFaq SET
CustConsltType = #{custConsltType}, FaqTypeDesc = #{faqTypeDesc}, FaqTitle = #{faqTitle},
FaqCntnts = #{faqCntnts}, ChnlCode = #{chnlCode}, State = #{state}, Remark = #{remark},
ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE FaqNo = #{faqNo}
